class AuditedPayments(private val inner: Payments, private val sink: AuditSink) : Payments by inner {
    override suspend fun pay(p: Payment): Receipt {
        val actor = currentSubject()
        sink.record(actor, "pay", p.id, "attempt")
        return try {
            inner.pay(p).also { sink.record(actor, "pay", p.id, "ok") }
        } catch (e: Exception) {
            sink.record(actor, "pay", p.id, "failed"); throw e
        }
    }
}
